  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Junta a imagem (foto real ou gerada pela IA) e calcula o enquadramento "cover" em 1080×1350
const p = $('Prepara a foto').first().json;
const arte = parseJSON($('Diretora de arte').first().json.output ?? '') || {};
let b64 = '';
if (p.modo === 'usar') {
  try { b64 = JSON.parse($('Lê a foto').first().json.foto).b64; } catch (e) {}
} else {
  const r = $('Gera a imagem').first().json;
  b64 = (r.data && r.data[0] && r.data[0].b64_json) || '';
}
if (!b64) return [{ json: { ok: false, erro: 'A IA de imagem não devolveu imagem.' } }];
const buf = Buffer.from(b64, 'base64');
function dims(x) {
  if (x[0] === 0x89 && x[1] === 0x50) return { w: x.readUInt32BE(16), h: x.readUInt32BE(20) };
  if (x[0] === 0xFF && x[1] === 0xD8) {
    let i = 2;
    while (i < x.length - 9) {
      if (x[i] !== 0xFF) { i++; continue; }
      const m = x[i + 1];
      if ([0xC0, 0xC1, 0xC2].includes(m)) return { h: x.readUInt16BE(i + 5), w: x.readUInt16BE(i + 7) };
      i += 2 + x.readUInt16BE(i + 2);
    }
  }
  return null;
}
const d = dims(buf) || { w: 1024, h: 1024 };
const W = 1080, H = 1350, esc = Math.max(W / d.w, H / d.h);
const rw = Math.ceil(d.w * esc), rh = Math.ceil(d.h * esc);
const faixa = String(arte.faixa_titulo || '').replace(/[\u{1F000}-\u{1FAFF}\u{2600}-\u{27BF}\u{FE0F}]/gu, '').replace(/"/g, '”').replace(/'/g, '’').trim().slice(0, 42);
const cor = /^#[0-9a-f]{6}$/i.test(arte.cor_faixa || '') ? arte.cor_faixa : '#111111';
// Fonte da faixa: diminui até o texto caber em 960 px (cada letra em negrito ocupa cerca de 0,72 do tamanho da fonte)
const fonteFaixa = faixa ? Math.max(30, Math.min(52, Math.floor(960 / (faixa.length * 0.72)))) : 52;
return [{ json: { ok: true, w: d.w, h: d.h, rw, rh, cx: Math.floor((rw - W) / 2), cy: Math.floor((rh - H) / 2), faixa, cor, fonteFaixa,
  faixaY: faixa ? 1160 : 1350, origem: p.modo === 'usar' ? 'foto do cliente' : 'gerada pela IA' },
  binary: { data: { data: b64, mimeType: p.modo === 'usar' ? (p.mime || 'image/jpeg') : 'image/jpeg', fileName: 'base.jpg' } } }];

// O Edit Image entrega a imagem como arquivo; aqui viramos texto (base64) para guardar no Redis
const itens = $input.all();
const saida = [];
for (let i = 0; i < itens.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  saida.push({ json: { n: itens[i].json.n, b64: buf.toString('base64'), kb: Math.round(buf.length / 1024) } });
}
return saida;

