let legenda = String(copy.legenda || '').trim().slice(0, 2000) || v.briefing.slice(0, 300);
if (tags.length) legenda += '\n\n' + tags.join(' ');
const rascunho = {
  id: v.id, k: v.k, status: 'aguardando', sessao: v.sessao, briefing: v.briefing, perfil: v.perfil,
  titulo: String(copy.titulo || '').slice(0, 120), legenda, alt: String(copy.alt_text || '').slice(0, 300),
  prompt_imagem: String(arte.prompt_imagem || '').slice(0, 1500), origem: base.origem, faixa: base.faixa,
  url: `${v.base}/webhook/post-ia-img?id=${v.id}`, kb: $input.first().json.kb,
  criadoEm: v.criadoEm, atualizadoEm: new Date().toISOString(),
};
return [{ json: { rascunho_str: JSON.stringify(rascunho) } }];

const b64 = $input.first().json.img;
if (!b64) return [{ json: { achou: false } }];
return [{ json: { achou: true }, binary: { data: { data: b64, mimeType: 'image/jpeg', fileName: 'slide.jpg', fileExtension: 'jpg' } } }];

const q = $('Ver post (GET)').first().json.query || {};
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;');
let r = null;
try { r = JSON.parse($input.first().json.rascunho || 'null'); } catch (e) {}
const casca = (corpo, refresh) => `<!DOCTYPE html><html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex">${refresh ? '<meta http-equiv="refresh" content="6">' : ''}<title>Aprovar post</title>
<style>*{box-sizing:border-box;margin:0;padding:0}body{font-family:system-ui,-apple-system,"Segoe UI",sans-serif;background:#fafafa;color:#262626;padding:20px 14px 60px}.w{max-width:520px;margin:0 auto}
