if (!r || q.k !== r.k) return [{ json: { codigo: 404, html: casca('<h1 style="margin-top:60px">Post não encontrado</h1>') } }];
if (r.status === 'gerando') return [{ json: { codigo: 200, html: casca('<div class="s"></div><h1>A equipe de IA está criando seu post</h1><p class="mu" style="text-align:center">Diretora de arte, copywriter e IA de imagem trabalhando. Esta página se atualiza sozinha (cerca de 2 minutos).</p>', true) } }];
if (r.status === 'erro_geracao') return [{ json: { codigo: 500, html: casca(`<h1>Não foi possível criar o post</h1><p class="mu" style="text-align:center">${esc(r.erro)}</p>`) } }];
const ST = { aguardando: '📝 Aguardando aprovação', publicado: '✅ Publicado', erro: '⚠️ Falhou ao publicar', descartado: '🗑️ Descartado' };
const pode = ['aguardando', 'erro'].includes(r.status);
const corpo = `<p style="margin-bottom:10px"><span class="tag">${ST[r.status] || esc(r.status)}</span> <span class="mu">imagem ${esc(r.origem)}</span>${r.permalink ? ` · <a href="${esc(r.permalink)}" target="_blank" rel="noopener">ver no Instagram</a>` : ''}</p>
${r.erro && r.status === 'erro' ? `<p class="msg er">${esc(r.erro)}</p>` : ''}
<div class="post"><img src="${esc(r.url)}" alt="${esc(r.alt)}"><div class="leg"><b>${esc(r.perfil || 'seu_perfil')}</b> ${esc(r.legenda)}</div></div>
${pode ? `<div class="box"><label for="leg">Legenda (pode editar)</label><textarea id="leg" maxlength="2200">${esc(r.legenda)}</textarea>
<label for="senha">Senha de publicação</label><input id="senha" type="password" autocomplete="off" placeholder="Só quem tem a senha publica">
<div class="bts"><button class="bt pub" data-a="publicar" type="button">🚀 Publicar agora</button><button class="bt" data-a="descartar" type="button">🗑️ Descartar</button></div><p class="msg" id="msg" role="status"></p></div>` : ''}
<p class="mu" style="margin-top:12px">Para mudar a imagem, volte ao chat e peça um ajuste: a Produtora cria uma nova versão.</p>
<script>document.querySelectorAll('[data-a]').forEach(function(b){b.addEventListener('click',function(){var a=b.getAttribute('data-a'),m=document.getElementById('msg');
if(a==='publicar'&&!confirm('Publicar agora no Instagram?'))return;document.querySelectorAll('[data-a]').forEach(function(x){x.disabled=true;});m.className='msg';m.textContent=a==='publicar'?'Publicando…':'Salvando…';
fetch('/webhook/post-ia-acao',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:${JSON.stringify(r.id)},k:${JSON.stringify(r.k)},acao:a,senha:document.getElementById('senha').value,legenda:document.getElementById('leg').value})})
.then(function(x){return x.json();}).then(function(j){if(!j.ok){m.className='msg er';m.textContent=j.erro||'Não foi possível.';document.querySelectorAll('[data-a]').forEach(function(x){x.disabled=false;});return;}m.className='msg ok';m.textContent=j.mensagem||'Feito!';setTimeout(function(){location.reload();},1500);})
.catch(function(){m.className='msg er';m.textContent='Falha de conexão.';document.querySelectorAll('[data-a]').forEach(function(x){x.disabled=false;});});});});</script>`;
return [{ json: { codigo: 200, html: casca(corpo) } }];

// 🔐 Senha para publicar na conta do Instagram (troque aqui)
const SENHA = '<SEGREDO_REMOVIDO>';
const b = $('Ação no post (POST)').first().json.body || {};
let r = null;
try { r = JSON.parse($input.first().json.rascunho || 'null'); } catch (e) {}
const nao = (erro, codigo = 400) => [{ json: { ok: false, erro, codigo } }];
if (!r || b.k !== r.k) return nao('Post não encontrado.', 404);
if (!['publicar', 'descartar'].includes(b.acao)) return nao('Ação inválida.');
if (b.acao === 'publicar' && b.senha !== SENHA) return nao('Senha de publicação incorreta.', 403);
if (r.status === 'publicado') return nao('Este post já foi publicado.');
const legenda = String(b.legenda ?? r.legenda).replace(/\r/g, '').trim().slice(0, 2200) || r.legenda;
const novo = { ...r, legenda, erro: '', atualizadoEm: new Date().toISOString() };
if (b.acao === 'descartar') novo.status = 'descartado';
return [{ json: { ok: true, acao: b.acao, id: r.id, url: r.url, legenda, rascunho_str: JSON.stringify(novo) } }];

// Junta o resultado da publicação com o rascunho e marca como publicado (ou erro)
const NO_ORIGEM = 'Valida ação do post';
const saida = [];
const origem = $(NO_ORIGEM).all();
const itens = $input.all();
for (let i = 0; i < itens.length; i++) {
  const o = origem[i] ? origem[i].json : origem[0].json;
  const r = JSON.parse(o.rascunho_str);
  const j = itens[i].json;
  if (j.error || !j.id) {
    const e = j.error;
    Object.assign(r, { status: 'erro', erro: 'O Instagram recusou: ' + String((e && (e.message || e.description)) || e || 'sem resposta').slice(0, 300) });
  } else {
    Object.assign(r, { status: 'publicado', media_id: j.id, permalink: j.permalink || '', publicadoEm: new Date().toISOString(), erro: '' });
  }
  r.atualizadoEm = new Date().toISOString();
  saida.push({ json: { id: r.id, ok: r.status === 'publicado', permalink: r.permalink || '', erro: r.erro || '', rascunho_str: JSON.stringify(r) } });
}
return saida;
